"""Sliding Window Median — two heaps with lazy deletion.

Elements leaving the window are marked in `_pending` and only discarded once
they surface at a heap top; balance counters keep the split correct meanwhile.

Time: O(n log k)   Space: O(k)
"""
import heapq
from collections import defaultdict
from typing import List


class Solution:
    def medianSlidingWindow(self, nums: List[int], k: int) -> List[float]:
        low, high = [], []                 # max-heap (negated), min-heap
        pending = defaultdict(int)

        for value in nums[:k]:
            heapq.heappush(low, -value)
        for _ in range(k // 2):
            heapq.heappush(high, -heapq.heappop(low))

        def median() -> float:
            if k % 2:
                return float(-low[0])
            return (-low[0] + high[0]) / 2.0

        def prune(heap, sign) -> None:
            while heap and pending[sign * heap[0]] > 0:
                pending[sign * heap[0]] -= 1
                heapq.heappop(heap)

        out = [median()]
        for i in range(k, len(nums)):
            out_value, in_value = nums[i - k], nums[i]
            pending[out_value] += 1
            balance = -1 if out_value <= -low[0] else 1

            if in_value <= -low[0]:
                balance += 1
                heapq.heappush(low, -in_value)
            else:
                balance -= 1
                heapq.heappush(high, in_value)

            if balance > 0:                # low has one element too many
                heapq.heappush(high, -heapq.heappop(low))
            elif balance < 0:
                heapq.heappush(low, -heapq.heappop(high))

            prune(low, -1)
            prune(high, 1)
            out.append(median())
        return out
